import 'accounting_curriculum.dart';

const ontologyCurriculum = <AccountingChapter>[
  AccountingChapter(
    title: 'Ontology foundations: concepts, entities and meaning',
    objectives: 'Define ontology in information and knowledge systems; distinguish a concept, entity, attribute, relationship and instance; explain why shared meaning matters in finance.',
    concept: 'An ontology is an explicit, structured representation of the concepts in a domain and the relationships among them. A finance ontology defines what terms such as Invoice, Supplier, Payment, Account, Journal, Cost Centre and Reporting Period mean, how they relate, and which rules apply. A concept is a general class (Supplier); an instance is a particular supplier record. An attribute describes an entity (supplier legal name, tax identifier, payment terms). A relationship connects concepts (Invoice is issued by Supplier; Payment settles Payable). A controlled vocabulary reduces ambiguity, while definitions, identifiers, cardinality and constraints make meaning usable by people and systems.',
    example: 'A business has three systems that each use the word “vendor”. Procurement means an approved supplier, AP means the party on an invoice, and the bank file means the payee. The ontology distinguishes Supplier, Invoice Party and Payment Beneficiary, then defines when they may refer to the same legal entity and when independent verification is required.',
    method: '1. Define the business domain and intended decisions. 2. Identify authoritative source documents and subject-matter owners. 3. Extract candidate terms from policies, processes, reports and systems. 4. Write precise definitions and examples. 5. Separate classes from individual records and attributes. 6. Assign stable identifiers and ownership. 7. Review ambiguous terms with finance, operations, tax, risk and technology stakeholders. 8. Publish a governed glossary and change process.',
    crossFunctional: 'AP defines invoice and payable states; Procurement defines supplier onboarding and purchase orders; Treasury defines payment instruction and beneficiary; GL defines account and journal; Tax defines tax registrations and treatments; Data Governance owns definitions, stewardship and quality; IT maps ontology terms to application fields and APIs.',
    formula: 'A useful concept specification = preferred term + definition + identifier + owner + attributes + relationships + constraints + examples + source. Do not treat a label match as proof that two records represent the same real-world entity.',
    assignment: 'Create a glossary of 20 finance terms. For each, provide a plain-language definition, one example, one non-example, business owner, source system and two related terms. Identify five ambiguous words that different departments currently use differently.',
    capstone: 'Produce a Finance Ontology Starter Pack for a fictional mid-sized company: scope statement, glossary, concept catalogue, ownership matrix, ambiguity register, version number and approval workflow.',
    notes: {'English':'An ontology makes domain concepts and their relationships explicit so people, processes and systems use consistent meanings.','Telugu':'ఒంటాలజీ అనేది ఒక రంగంలోని భావనలు, వాటి అర్థాలు మరియు పరస్పర సంబంధాలను స్పష్టంగా నిర్వచించే నిర్మాణం. దీని వల్ల వ్యక్తులు, ప్రక్రియలు, వ్యవస్థలు ఒకే అర్థాన్ని ఉపయోగిస్తాయి.','Hindi':'ऑन्टोलॉजी किसी क्षेत्र की अवधारणाओं, उनके अर्थ और आपसी संबंधों को स्पष्ट रूप से परिभाषित करती है। इससे लोग, प्रक्रियाएँ और प्रणालियाँ एक समान अर्थ का उपयोग करती हैं।'},
    flashcards: [{'q':'What is an ontology?','a':'A formal, explicit representation of domain concepts, relationships and constraints.'},{'q':'What is a class?','a':'A category of things, such as Supplier or Invoice.'},{'q':'What is an instance?','a':'A particular member of a class, such as one supplier record.'},{'q':'What is an attribute?','a':'A property describing an entity, such as invoice date or currency.'},{'q':'Why use stable identifiers?','a':'To distinguish entities reliably even when names or labels change.'}],
    questions: [
      AccountingQuestion('What does a domain ontology primarily describe?',['Only screen layouts','Concepts, relationships and constraints in a domain','Only database passwords','A list of software licences'],1,'An ontology formalises domain meaning, relationships and applicable constraints.'),
      AccountingQuestion('“Supplier” is a general category. One registered supplier is best described as:',['An instance','A relationship','A report filter','A formula'],0,'A particular supplier record is an instance of the Supplier class.'),
      AccountingQuestion('Which is an attribute of an invoice?',['Issued by','Settles','Invoice date','Approved by department'],2,'Invoice date is a property; issued by and settles are relationships.'),
      AccountingQuestion('Why is a shared finance glossary useful?',['It removes the need for controls','It reduces ambiguity across teams and systems','It guarantees every source record is correct','It replaces accounting standards'],1,'Shared definitions improve communication and mapping, but do not replace validation or controls.'),
      AccountingQuestion('Two records have the same supplier name. What is the safest conclusion?',['They are certainly the same entity','They are certainly different entities','Name alone is insufficient; compare governed identifiers and evidence','Merge them automatically'],2,'Names can collide or vary; identity resolution needs reliable identifiers and evidence.')
    ],
  ),
  AccountingChapter(
    title: 'Finance domain model: entities, attributes and relationships',
    objectives: 'Model core finance entities; distinguish master, transactional and reference data; define relationship direction and cardinality; understand identifiers and entity resolution.',
    concept: 'A finance domain model organises the key objects used in business activity. Master data describes relatively stable business entities such as Supplier, Customer, Employee, Legal Entity, Bank Account and Chart of Accounts. Transaction data records events such as Purchase Order, Invoice, Receipt, Journal and Payment. Reference data supplies controlled values such as Currency, Country, Tax Code and Payment Terms. Each entity needs a definition, identifier, lifecycle, owner and quality rules. Relationships may be one-to-one, one-to-many or many-to-many. For example, one supplier may issue many invoices; one payment run may contain many payment instructions; one invoice may be settled by multiple partial payments.',
    example: 'Invoice INV-104 is issued by Supplier S-20, billed to Legal Entity LE-01, denominated in INR, coded to Cost Centre CC-14 and settled by two payments. The model captures these links rather than storing disconnected labels. It also records that the invoice has one currency, while a supplier may transact in many currencies.',
    method: '1. List core entities and classify them as master, transaction or reference data. 2. Define a primary business identifier for each. 3. Identify attributes, data types, mandatory status and allowed values. 4. Draw relationships and state cardinality. 5. Define lifecycle states and valid transitions. 6. Identify source-of-truth systems and stewardship roles. 7. Specify duplicate detection and merge controls. 8. Validate the model against real process scenarios.',
    crossFunctional: 'Procurement owns supplier and purchase-order context; AP owns invoice capture and matching; Treasury owns bank account and payment execution context; HR owns employee master; Tax owns tax-code interpretation; GL owns accounts and journals; Enterprise Data Architecture validates identifiers, relationships and integration contracts.',
    formula: 'Relationship example: Supplier 1 → 0..* Invoice; Invoice 1 → 1 Currency; Invoice 1 → 0..* Settlement Allocation; Payment 1 → 1..* Payment Instruction. Cardinality must reflect the actual business policy, not an assumption made by a developer.',
    assignment: 'Draw a conceptual entity relationship model for Supplier, Purchase Order, Goods Receipt, Invoice, Payment, Bank Account, Legal Entity, Currency and GL Account. Mark primary identifiers, at least ten relationships and cardinalities. Explain one many-to-many relationship.',
    capstone: 'Create a finance data dictionary and ER model for procure-to-pay. Include entity definitions, identifiers, required fields, data owners, cardinalities, lifecycle states and five data-quality validation rules.',
    notes: {'English':'A domain model identifies the important finance objects, their properties and how they connect across business processes.','Telugu':'డొమైన్ మోడల్ ఆర్థిక ప్రక్రియల్లో ఉపయోగించే ముఖ్యమైన వస్తువులు, వాటి లక్షణాలు, వాటి మధ్య సంబంధాలను చూపిస్తుంది.','Hindi':'डोमेन मॉडल वित्तीय प्रक्रियाओं की प्रमुख इकाइयों, उनके गुणों और उनके आपसी संबंधों को दर्शाता है।'},
    flashcards: [{'q':'What is master data?','a':'Relatively stable data about entities such as suppliers, customers and accounts.'},{'q':'What is transaction data?','a':'Records of business events such as invoices, receipts, journals and payments.'},{'q':'What is reference data?','a':'Controlled values such as currency codes, tax codes and payment terms.'},{'q':'What does 1-to-many mean?','a':'One record on one side can relate to multiple records on the other side.'},{'q':'What is entity resolution?','a':'Determining whether different records refer to the same real-world entity using reliable evidence.'}],
    questions: [
      AccountingQuestion('Which is normally reference data?',['Supplier invoice','Currency code','Customer receipt','Journal entry'],1,'Currency codes are controlled reference values.'),
      AccountingQuestion('One supplier can issue many invoices. This is:',['One-to-one','One-to-many','Many-to-one only','No relationship'],1,'A supplier may be associated with multiple invoices.'),
      AccountingQuestion('Which identifier is usually safer for matching legal entities than display name alone?',['A governed unique registration identifier','A shortened nickname','A free-text description','A screen colour'],0,'A governed identifier is more stable and discriminating than a display name.'),
      AccountingQuestion('A payment run contains multiple payment instructions. Which relationship is likely?',['One-to-many','One-to-one always','No relationship','Many-to-zero'],0,'A payment run commonly groups multiple payment instructions.'),
      AccountingQuestion('Who should validate the business meaning of an entity?',['Only the UI designer','Relevant domain owner or steward with stakeholders','Any end user without review','The database engine'],1,'Business owners and stewards validate meaning; technology teams implement it.')
    ],
  ),
  AccountingChapter(
    title: 'Process ontology: events, states and controls',
    objectives: 'Represent finance processes as events and state transitions; distinguish status from event; map P2P and O2C; connect control points, evidence and exception ownership.',
    concept: 'A process ontology describes the business events, actors, objects, states and rules that make a process work. An event is something that happened at a point in time; a state describes the current condition of an object. An invoice may move from Captured to Validated, Matched, Approved, Scheduled, Paid or Rejected. A status label alone is not enough: the model should define who can cause a transition, prerequisites, timestamps, evidence and permitted next states. Events should be traceable and preferably immutable; corrections are represented by linked reversal or correction events rather than silently rewriting history. Controls are attached to transitions, such as duplicate checks before approval or independent bank-detail verification before payment.',
    example: 'An invoice shows “Paid” in the AP system, but the bank rejects the payment. The ontology distinguishes Payment Instruction Created, Submitted, Accepted, Settled and Rejected. AP cannot treat submission as settlement. A bank rejection event changes the payment state, reopens the payable according to policy and creates an owned exception with evidence.',
    method: '1. Select a process boundary and outcome. 2. Identify actors, objects and business events. 3. Define states and valid transitions. 4. Attach preconditions, authority and evidence to each transition. 5. Identify control failures and exception routes. 6. Define event timestamps and correlation identifiers. 7. Reconcile system states with external evidence. 8. Test normal, rejected, reversed, duplicate and delayed scenarios.',
    crossFunctional: 'AP validates invoices and exceptions; Procurement resolves PO/receipt mismatches; Treasury submits and reconciles payments; Banks and payment providers return external statuses; AR manages customer billing and cash application; GL records accounting impact; Risk and Audit test authority, evidence and segregation of duties.',
    formula: 'A valid transition = current state + qualifying event + authorised actor + satisfied preconditions + retained evidence → next state. Example: Approved → Payment Submitted is not equivalent to Approved → Payment Settled.',
    assignment: 'Map an invoice lifecycle with at least eight events and six states. For every transition, state actor, precondition, evidence, control, timestamp and exception route. Include a rejected payment and a reversal.',
    capstone: 'Design a process ontology for AP invoice-to-pay and AR order-to-cash. Create event catalogues, state machines, control mappings, exception ownership and a reconciliation report showing source-to-ledger traceability.',
    notes: {'English':'Events record what happened; states describe where an object is now. A controlled process model defines valid transitions, authority, evidence and exception handling.','Telugu':'ఈవెంట్ అంటే జరిగిన సంఘటన; స్టేట్ అంటే ఒక వస్తువు ప్రస్తుతం ఉన్న స్థితి. నియంత్రిత ప్రక్రియ నమూనా సరైన మార్పులు, అధికారం, ఆధారాలు, మినహాయింపుల పరిష్కారాన్ని నిర్వచిస్తుంది.','Hindi':'इवेंट बताता है कि क्या हुआ; स्टेट बताता है कि कोई वस्तु अभी किस स्थिति में है। नियंत्रित प्रक्रिया मॉडल वैध बदलाव, अधिकार, प्रमाण और अपवाद समाधान तय करता है।'},
    flashcards: [{'q':'What is an event?','a':'A business occurrence recorded at a point in time.'},{'q':'What is a state?','a':'The current condition of an entity or transaction.'},{'q':'Why distinguish submitted from settled?','a':'Submission does not prove funds moved or settlement completed.'},{'q':'What is a state transition?','a':'A permitted change from one defined state to another after required conditions are met.'},{'q':'Why retain correction events?','a':'To preserve history, traceability and an audit trail.'}],
    questions: [
      AccountingQuestion('“Payment submitted” and “payment settled” should be modelled as:',['The same event','Distinct states/events with different meanings','A supplier attribute','A currency code'],1,'Submission and settlement are distinct milestones and must not be conflated.'),
      AccountingQuestion('What should authorise a transition to Approved?',['A valid approval by an authorised role with required evidence','Any status text typed by a user','A successful page refresh','A supplier display name'],0,'Approval requires authority, policy conditions and retained evidence.'),
      AccountingQuestion('Why are immutable event histories valuable?',['They remove the need for reconciliations','They preserve traceability and explain how the current state arose','They guarantee zero fraud','They replace source documents'],1,'An event history supports auditability and investigation.'),
      AccountingQuestion('A bank rejects a submitted payment. What should happen?',['Keep it marked settled','Record the rejection and route the exception for resolution','Delete the original instruction','Post revenue'],1,'The rejection must be recorded and reconciled; the payable treatment follows policy and evidence.'),
      AccountingQuestion('Which is a control point?',['Duplicate invoice validation before approval','Changing a label colour','Hiding failed transactions','Removing audit logs'],0,'A duplicate check before approval is a preventive control.')
    ],
  ),
  AccountingChapter(
    title: 'Semantic interoperability: mapping systems and data',
    objectives: 'Explain semantic interoperability; distinguish syntactic and semantic mapping; map source fields to canonical concepts; understand APIs, lineage, metadata and data contracts.',
    concept: 'Syntactic interoperability means systems can exchange data in a compatible format; semantic interoperability means they interpret the exchanged data consistently. A canonical model provides shared business concepts while allowing each application to retain its own schema. Mapping must document source field, target concept, transformation, units, code lists, null handling, effective dates, lineage and accountable owner. For example, “supplier_id”, “vendor_no” and “payee_ref” may look similar but may represent different identifiers. Data contracts specify expected structure, meaning, quality, availability and change rules. APIs and event streams should carry stable identifiers and explicit statuses rather than relying on ambiguous free text.',
    example: 'An ERP stores invoice date as DD-MM-YYYY, an OCR service returns ISO date, and a payment provider sends a timestamp with timezone. The integration maps all three to a canonical Invoice Date or Payment Event Time with documented timezone and precision rules. It does not silently treat invoice date, posting date and settlement date as interchangeable.',
    method: '1. Inventory source systems, schemas and data owners. 2. Identify canonical concepts and definitions. 3. Map each source field with transformation and validation rules. 4. Preserve original values and source lineage. 5. Standardise codes, units, currencies and timezones. 6. Define API/data-contract versioning and backward compatibility. 7. Test nulls, duplicates, late events, retries and schema changes. 8. Reconcile record counts and financial control totals after exchange.',
    crossFunctional: 'Finance defines meaning and reconciliation controls; Enterprise Architecture defines canonical patterns; ERP and integration teams implement mappings; Data Engineering monitors pipelines and lineage; Cybersecurity controls access and integrity; Audit verifies source-to-report traceability.',
    formula: 'Mapping specification = source system + source field + target concept + transformation + validation + lineage + owner + version. Semantic equivalence must be justified by definition and business rules, not by similar field names.',
    assignment: 'Create a mapping table for 12 fields across an ERP, OCR invoice service and payment provider. Include supplier identifier, invoice number, invoice date, posting date, currency, gross amount, tax amount, due date, payment reference, status, bank account token and settlement timestamp.',
    capstone: 'Design a canonical invoice and payment data contract for three systems. Include JSON examples, field definitions, status semantics, validation rules, versioning policy, lineage and reconciliation controls.',
    notes: {'English':'Semantic interoperability means connected systems agree on what exchanged data represents, not merely how the data is formatted.','Telugu':'సెమాంటిక్ ఇంటర్‌ఆపరబిలిటీ అంటే డేటా ఏ ఫార్మాట్‌లో ఉందో మాత్రమే కాదు, ఆ డేటా ఏ అర్థాన్ని సూచిస్తుందో అనుసంధానమైన వ్యవస్థలు ఒకే విధంగా అర్థం చేసుకోవడం.','Hindi':'सेमांटिक इंटरऑपरेबिलिटी का अर्थ है कि जुड़े हुए सिस्टम केवल डेटा का प्रारूप ही नहीं, बल्कि उसके व्यावसायिक अर्थ को भी समान रूप से समझें।'},
    flashcards: [{'q':'What is syntactic interoperability?','a':'Ability to exchange data using compatible structures and formats.'},{'q':'What is semantic interoperability?','a':'Consistent interpretation of the meaning of exchanged data.'},{'q':'What is a canonical model?','a':'A shared conceptual representation used to map different system schemas.'},{'q':'What is data lineage?','a':'Traceability of data origin, transformations and destinations.'},{'q':'What is a data contract?','a':'An agreement defining data structure, meaning, quality, availability and change expectations.'}],
    questions: [
      AccountingQuestion('Two systems exchange valid JSON but interpret “date” differently. Which issue remains?',['Semantic interoperability','Network connectivity','Screen resolution','Authentication only'],0,'Compatible syntax does not guarantee shared meaning.'),
      AccountingQuestion('A canonical model is used to:',['Force every system to use identical database tables','Provide shared concepts for mapping different system schemas','Remove data ownership','Eliminate validation'],1,'Canonical concepts support consistent mapping without requiring identical internal schemas.'),
      AccountingQuestion('Which mapping is unsafe without further definition?',['Invoice date → invoice date','Supplier number → payment beneficiary ID','Currency code → currency code with validation','Gross amount → gross amount with currency'],1,'Supplier identity and payment beneficiary may be distinct concepts and need explicit rules.'),
      AccountingQuestion('Why preserve source lineage?',['To trace data origin and transformations','To make reports longer','To avoid testing','To hide data changes'],0,'Lineage supports investigation, reconciliation and audit.'),
      AccountingQuestion('What should a data contract specify?',['Only field labels','Structure, semantics, quality and change expectations','Only UI colours','Only server location'],1,'A useful contract governs structure and meaning as well as quality and evolution.')
    ],
  ),
  AccountingChapter(
    title: 'Governance, quality, lineage and ontology operations',
    objectives: 'Establish ontology governance; define stewardship and change control; apply data-quality dimensions; connect lineage, metadata, privacy, access and audit; measure adoption.',
    concept: 'An ontology remains useful only when definitions, mappings and rules are governed over time. Governance assigns accountable owners, stewards, approvers and technical custodians. A change process records the request, rationale, impact assessment, compatibility decision, approval, effective date, version and communication. Data quality can be assessed through accuracy, completeness, consistency, timeliness, validity and uniqueness. Lineage records where data originated and how it was transformed. Metadata describes data context, ownership and constraints. Privacy and security require purpose limitation, minimisation, role-based access, retention and protection of sensitive identifiers. Quality exceptions need severity, owner, due date, root cause and closure evidence.',
    example: 'A regulator changes a tax identifier format. The ontology steward opens a change request, assesses affected supplier master records, OCR validation, ERP interfaces, tax reports and payment controls, agrees a versioned rule, tests historical and new records, communicates the effective date and monitors exceptions. The old definition remains available for audit history.',
    method: '1. Appoint domain owner, steward, approver and technical custodian. 2. Establish glossary and model repositories with version history. 3. Define quality dimensions, thresholds and exception workflows. 4. Register source-to-target lineage and critical data elements. 5. Classify sensitive data and apply least-privilege access. 6. Assess proposed changes for downstream impact and compatibility. 7. Test mappings and controls before release. 8. Monitor adoption, defects, stale definitions and remediation ageing.',
    crossFunctional: 'Finance process owners approve business definitions; Data Governance coordinates stewardship and quality; Legal/Privacy advises lawful use and retention; Cybersecurity defines access and protection; IT owns implementation and monitoring; Risk/Audit independently assesses controls and evidence.',
    formula: 'Completeness rate = populated required values ÷ required values expected × 100%. Uniqueness exception rate = duplicate candidate records ÷ records assessed × 100%. Always document the population, exclusions, time window and threshold.',
    assignment: 'Create a governance RACI and change request for a proposed new “Payment Beneficiary” concept. Include affected systems, privacy risks, data-quality checks, approval roles, testing evidence, version and rollback/compatibility plan.',
    capstone: 'Build an Ontology Governance Operating Model with glossary, model versioning, stewardship RACI, quality scorecard, lineage register, privacy classification, change workflow, issue log and quarterly review agenda.',
    notes: {'English':'Governance keeps shared definitions accurate, secure, owned and compatible as finance processes, regulations and systems change.','Telugu':'గవర్నెన్స్ ద్వారా ఆర్థిక ప్రక్రియలు, నిబంధనలు, వ్యవస్థలు మారుతున్నప్పటికీ పంచుకున్న నిర్వచనాలు సరైనవిగా, సురక్షితంగా, బాధ్యతతో, అనుకూలంగా ఉంటాయి.','Hindi':'गवर्नेंस यह सुनिश्चित करता है कि वित्तीय प्रक्रियाओं, नियमों और प्रणालियों के बदलने पर भी साझा परिभाषाएँ सही, सुरक्षित, जिम्मेदार और संगत रहें।'},
    flashcards: [{'q':'Who is a data steward?','a':'A role responsible for maintaining and coordinating the quality and meaning of a data domain.'},{'q':'Name four data-quality dimensions.','a':'Accuracy, completeness, consistency, timeliness, validity and uniqueness.'},{'q':'What is lineage?','a':'A record of data origin, movement and transformation.'},{'q':'Why version an ontology?','a':'To manage change, compatibility, impact and audit history.'},{'q':'What is least privilege?','a':'Granting only the minimum access needed for an authorised task.'}],
    questions: [
      AccountingQuestion('Which role normally coordinates definitions and data-quality issues for a domain?',['Data steward','Unassigned end user','External customer','Payment gateway'],0,'The steward coordinates the domain’s definitions and quality with accountable owners.'),
      AccountingQuestion('Which is a recognised data-quality dimension?',['Completeness','Font size','Brand colour','Screen brightness'],0,'Completeness is a core data-quality dimension.'),
      AccountingQuestion('A proposed ontology change should be released after:',['A developer changes a label','Impact assessment, approval, testing and versioned communication','Deleting the old definition','Skipping downstream analysis'],1,'Governed change requires impact analysis, approval, testing and traceable release.'),
      AccountingQuestion('Least privilege means:',['Everyone has administrator access','Only necessary authorised access is granted','No one can access data','Passwords are shared'],1,'Least privilege limits access to what is required for an authorised task.'),
      AccountingQuestion('Which metric needs a clearly defined denominator?',['Completeness rate','A colour palette','A page title','A file name'],0,'Quality metrics are meaningful only when population and denominator are explicit.')
    ],
  ),
];
